import {createAmbience,PRESETS} from './kfb-ambience.v1.mjs';
const host=window.KFBAudioSite,container=document.createElement('div');container.className='panel';container.id='atmosphere';
container.innerHTML=`<style>
#atmosphere .at-controls{display:flex;flex-wrap:wrap;gap:12px;align-items:end}#atmosphere label{display:grid;gap:5px}#atmosphere select{max-width:200px}#at-sky{height:100px;position:relative;overflow:hidden;border-radius:12px;background:linear-gradient(#476e89,#a6b8a1);margin:14px 0;transition:background 1s}#at-sky.night{background:linear-gradient(#182332,#354b52)}#at-sky.flash:after{content:'';position:absolute;inset:0;background:white;opacity:.85}#at-leaf{display:inline-block;position:absolute;bottom:18px;left:45%;font-size:24px}#at-sky small{position:absolute;left:12px;top:10px;color:white}#at-diagnostics{max-height:320px;overflow:auto;white-space:pre-wrap}#at-status{display:block;margin:12px 0}#atmosphere .at-links{display:flex;gap:16px;flex-wrap:wrap}
</style><div class="eyebrow">AUDIO OWNER · V-458 · R1 / EAR REVIEW OPEN</div><h2>ATMOSPHÄRE</h2><p class="tiny">Leise Umgebung, wechselnde Tierstimmen, Wetter und räumliches Wasser. Start spielt nur Atmosphäre; Musik ist optional.</p>
<div class="at-controls"><label>Biom<select id="at-biome">${Object.entries(PRESETS).map(([id,p])=>`<option value="${id}">${p.label}</option>`).join('')}</select></label><label>Tageszeit<select id="at-time"><option value="morning">Morgen</option><option value="day" selected>Tag</option><option value="evening">Abend</option><option value="night">Nacht</option></select></label><label>Wetter<select id="at-weather"><option value="clear">Klar</option><option value="rain-light">Leichter Regen</option><option value="rain-heavy">Starker Regen</option><option value="thunderstorm">Gewitter</option><option value="snow">Schnee · gedämpft</option><option value="storm">Sturm / Wind</option></select></label><label>Wind <output id="at-wind-out">0.20</output><input id="at-wind" type="range" min="0" max="1" step=".01" value=".2"></label></div>
<div id="at-sky"><small>Studio-Wettervorschau · ein Audio-Zeitgeber · kein World-Umbau</small><span id="at-leaf">❧</span></div>
<div class="at-controls"><button class="btn primary" id="at-start">Atmosphäre starten</button><button class="btn" id="at-stop">Alles hier stoppen</button><button class="btn" id="at-music" aria-pressed="false">Musik: aus</button><button class="btn" id="at-speech">Sprachtest</button><label>Blitzentfernung<select id="at-distance"><option value="343">343 m · 1 s</option><option value="1029">1029 m · 3 s</option><option value="3430">3430 m · 10 s</option></select></label><button class="btn" id="at-lightning">Blitz → Donner</button></div>
<output id="at-status" aria-live="polite">Gestoppt. Kein Autoplay. Bestehende Footsteps bleiben unverändert.</output><div class="at-links"><a href="./ambience/LICENCES.md" target="_blank">Quellen &amp; Lizenzen</a><a href="./ambience/licence-register.json" target="_blank">Dateien &amp; SHA256</a><a href="./ambience/CONSUMER.md" target="_blank">WS1-Anschluss</a></div><details><summary>Messungen &amp; offene Klanglücken</summary><p class="tiny">Dschungel-Nacht nutzt vorläufig den freigegebenen Morgen-Donor; keine erfundenen Affen oder benannten Vogelarten. Drei Minuten pro Biom bitte nach Gehör abnehmen.</p><pre id="at-diagnostics"></pre></details>`;
document.querySelector('#soundscape').prepend(container);
const shortcut=document.createElement('button');shortcut.textContent='Atmosphäre';shortcut.id='at-shortcut';shortcut.onclick=()=>{document.querySelector('[data-view="soundscape"]').click();container.scrollIntoView({block:'start'});};document.querySelector('.tabs').append(shortcut);
const $=id=>container.querySelector('#'+id);let engine,initializing,run=0,music=false,musicRun=0,utterance,voiceOwned=false,flashes=[],lastPaint=0,wind=.2,nextAutoFlash=Infinity,fixtureStart=null;
async function ensure(){if(engine)return engine;if(initializing)return initializing;initializing=(async()=>{const g=await host.resume();engine=await createAmbience({audioContext:g.ctx,destinations:g.buses,onWind:d=>{wind=d.value;window.dispatchEvent(new CustomEvent('kfb:wind',{detail:d}));}});return engine;})().finally(()=>initializing=null);return initializing;}
function state(){return {biome:$('at-biome').value,timeOfDay:$('at-time').value,weather:$('at-weather').value,wind:Number($('at-wind').value)};}
function water(){return state().biome==='beach'?[{id:'shore',kind:'beach',position:{x:12,y:0,z:-8}}]:state().biome==='pond'?[{id:'stream',kind:'river',position:{x:8,y:0,z:-7}}]:[];}
function status(s){$('at-status').textContent=s;}
async function update(){if(!engine)return;await engine.setContext(state());engine.setWaterEmitters(water());nextAutoFlash=host.audioContext.currentTime+15;}
function stop(){run++;musicRun++;engine?.stop();if(music)host.adaptiveMusic.stop();music=false;$('at-music').textContent='Musik: aus';$('at-music').setAttribute('aria-pressed','false');if(utterance)window.speechSynthesis.cancel();if(voiceOwned)host.musicContext.setVoiceActive(false,{source:'ambience-studio-stop'});voiceOwned=false;utterance=null;flashes=[];fixtureStart=null;$('at-sky').classList.remove('flash');status('Gestoppt · Atmosphäre, ausstehender Donner und hier gestartete Musik aus.');paint();}
async function start(){const token=++run;$('at-start').disabled=true;status('Freigegebene Aufnahmen werden geprüft und decodiert …');try{const e=await ensure();if(token!==run)return;await update();await e.start();if(token!==run){e.stop();return;}e.setWaterEmitters(water());fixtureStart=host.audioContext.currentTime;status('Läuft · '+PRESETS[state().biome].label+' · Hörprüfung offen.');}catch(err){engine?.stop();status('Nicht gestartet: '+err.message);}finally{$('at-start').disabled=false;paint();}}
function lightning(){if(!engine?.snapshot().active){status('Bitte zuerst Atmosphäre starten.');return;}const at=host.audioContext.currentTime+.08,id='studio-'+crypto.randomUUID(),distanceM=Number($('at-distance').value),cue=engine.emit({type:'lightning',id,at,distanceM,azimuth:-.4});if(cue)flashes.push({...cue,shown:false});nextAutoFlash=at+20+Math.random()*18;status(`Blitz zuerst · Donner nach ${(distanceM/343).toFixed(2)} s.`);}
function paint(){if(!engine)return;const s=engine.snapshot(),t=host.audioContext.currentTime;for(const f of flashes)if(!f.shown&&t>=f.flashAt){f.shown=true;f.visualAt=t;f.visualDriftMs=(t-f.flashAt)*1000;}flashes=flashes.filter(f=>t<f.flashAt+12);$('at-sky').classList.toggle('flash',flashes.some(f=>f.shown&&t-f.visualAt<.12));$('at-sky').classList.toggle('night',['night','evening'].includes(state().timeOfDay));$('at-leaf').style.transform=`translateX(${Math.sin(t*(.5+wind*1.5))*wind*70}px) rotate(${Math.sin(t*1.3)*wind*35}deg)`;
 if(s.active&&state().weather==='thunderstorm'&&t>=nextAutoFlash)lightning();if(t-lastPaint>.25||!s.active){lastPaint=t;$('at-diagnostics').textContent=JSON.stringify({revision:'0.8.0',elapsedSeconds:fixtureStart==null?0:Math.round(t-fixtureStart),hostAudioContexts:host.audioContextsCreated,...s,flashMeasurements:flashes,log:s.log.slice(-16)},null,2);}}
host.registerAudioTick(()=>{if(!engine)return;engine.setMix(host.getMixActivity());engine.tick();paint();});
for(const id of ['at-biome','at-time','at-weather','at-wind'])$(id).addEventListener('input',()=>{$('at-wind-out').textContent=Number($('at-wind').value).toFixed(2);update().catch(e=>status(e.message));});
$('at-start').onclick=start;$('at-stop').onclick=stop;$('at-lightning').onclick=lightning;
$('at-music').onclick=async()=>{const token=++musicRun;try{if(music){host.adaptiveMusic.stop();music=false;}else{status('Bestehendes D-Musikdeck wird geladen …');await host.adaptiveMusic.startDeck('D');if(token!==musicRun){host.adaptiveMusic.stop();return;}music=true;}$('at-music').setAttribute('aria-pressed',String(music));$('at-music').textContent='Musik: '+(music?'an':'aus');status(music?'D-Musik läuft · Atmosphäre senkt sich weich um 5 dB.':'Musik aus · Atmosphäre erholt sich weich.');}catch(e){status('Musik nicht gestartet: '+e.message);}};
$('at-speech').onclick=()=>{if(!('speechSynthesis' in window)){status('Browser-Sprachausgabe nicht verfügbar.');return;}if(utterance)window.speechSynthesis.cancel();utterance=new SpeechSynthesisUtterance('A quiet place, a little breeze, and room for us to talk.');utterance.lang='en-GB';utterance.rate=.9;utterance.onstart=()=>{voiceOwned=true;host.musicContext.setVoiceActive(true,{source:'ambience-studio-speech'});};utterance.onend=utterance.onerror=()=>{if(voiceOwned)host.musicContext.setVoiceActive(false,{source:'ambience-studio-speech-end'});voiceOwned=false;utterance=null;};speechSynthesis.speak(utterance);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
window.KFBAudioSite.ambience={getSnapshot:()=>engine?.snapshot()||{active:false,moduleCreatedAudioContexts:0},stop};
if(location.hash==='#atmosphere')shortcut.click();
